function gtmV350SteamArtworkCandidates(appId) {
    const id = normalizeSteamAppId(appId);
    if (!id) return [];
    const overview = getSteamAppOverview(id);
    const urls = [];
    const seenObjects = new Set();
    const add = (value) => {
        const raw = String(value || '').trim();
        if (!raw) return;
        if (!/^(https?:|data:|blob:|file:)/i.test(raw)) return;
        if (!urls.includes(raw)) urls.push(raw);
    };
    const preferredKeys = [
        'library_capsule', 'libraryCapsule', 'library_capsule_url', 'libraryCapsuleUrl',
        'm_strLibraryCapsuleURL', 'm_strLibraryCapsuleUrl', 'strLibraryCapsuleURL',
        'header_image', 'headerImage', 'header_image_url', 'headerImageUrl',
        'm_strHeaderURL', 'm_strHeaderUrl', 'strHeaderURL',
        'hero_image', 'heroImage', 'hero_image_url', 'heroImageUrl',
        'm_strHeroURL', 'm_strHeroUrl', 'strHeroURL',
        'capsule', 'capsule_url', 'capsuleUrl', 'm_strCapsuleURL', 'm_strCapsuleUrl',
        'icon', 'icon_url', 'iconUrl', 'm_strIconURL', 'm_strIconUrl',
        'logo', 'logo_url', 'logoUrl', 'm_strLogoURL', 'm_strLogoUrl',
        'image', 'image_url', 'imageUrl'
    ];
    const scan = (source, depth = 0) => {
        if (!source || typeof source !== 'object' || depth > 2 || seenObjects.has(source)) return;
        seenObjects.add(source);
        for (const key of preferredKeys) add(source[key]);
        for (const [key, value] of Object.entries(source)) {
            if (typeof value === 'string' && /(image|art|capsule|header|hero|logo|icon)/i.test(key)) add(value);
            else if (value && typeof value === 'object' && depth < 2 && /(asset|image|art|capsule|header|hero|logo|icon|media)/i.test(key)) scan(value, depth + 1);
        }
    };
    scan(overview);
    scan(overview?.m_assets);
    scan(overview?.assets);
    scan(overview?.library_assets);
    scan(overview?.m_libraryAssets);
    if (id < 0x80000000) {
        add(`https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/${id}/library_hero.jpg`);
        add(`https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/${id}/capsule_616x353.jpg`);
        add(`https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/${id}/header.jpg`);
        add(`https://cdn.cloudflare.steamstatic.com/steam/apps/${id}/library_hero.jpg`);
        add(`https://cdn.cloudflare.steamstatic.com/steam/apps/${id}/header.jpg`);
    }
    return urls;
}
