    // again never shows it. A subsequent real media event must do that.
    SP_REACT.useEffect(() => {
        if (!info.eligible && info.audio.state !== 'idle') {
            clearTimer(hideTimer);
            visibleRef.current = false;
            setVisible(false);
        }
    }, [info.eligible]);

    const [progressTick, setProgressTick] = SP_REACT.useState(0);
    SP_REACT.useEffect(() => {
        if (!visible || quickAccessVisible || !displayInfo || displayInfo.stateLabel !== 'Playing') return;
        const timer = setInterval(() => setProgressTick((value) => value + 1), 500);
        return () => clearInterval(timer);
    }, [visible, quickAccessVisible, displayInfo?.stateLabel, displayInfo?.title]);

    const visualizerLevels = usePassiveMiniVisualizer(
        Boolean(presentation.visualizer),
        Boolean(visible && !quickAccessVisible && displayInfo?.stateLabel === 'Playing')
    );

    if (!visible || quickAccessVisible || !displayInfo)
        return null;

    void progressTick;
    const h = window.SP_REACT.createElement;
    const source = displayInfo.source || 'GAME THEME MUSIC';
    const surfaceLabel = displayInfo.surfaceLabel || '';
    const title = displayInfo.title || 'Now playing';
    const stateLabel = displayInfo.stateLabel || '';
    const artwork = String(displayInfo.artwork || '');
    const nextTitle = String(displayInfo.nextTitle || '');
    const trackPosition = Number(displayInfo.trackPosition || 0);
    const trackTotal = Number(displayInfo.trackTotal || 0);
    const provider = String(displayInfo.provider || '');
