function shouldSkipAudioDownload(videoId) {
    return !videoId.length;
}

const AUDIO_FILE_EXTENSIONS = [
    'mp3',
    'ogg',
    'flac',
    'm4a',
    'wav',
    'aac',
    'opus',
    'webm',
    'weba',
    'mp4'
];
function getAudioImportPath(home, location) {
    const normalizedHome = home.replace(/\/+$/, '') || '/';
    if (location === 'home')
        return normalizedHome;
    const folder = location === 'music' ? 'Music' : 'Downloads';
    return normalizedHome === '/' ? `/${folder}` : `${normalizedHome}/${folder}`;
}

